  `anio_compra` int DEFAULT NULL,
  `fecha_alta` datetime DEFAULT CURRENT_TIMESTAMP,
  `fecha_baja` datetime DEFAULT NULL,
  `estado` enum('ACTIVO','REPARACION','HISTORICO','BAJA') COLLATE utf8mb4_unicode_ci DEFAULT 'ACTIVO',
  `observaciones` text COLLATE utf8mb4_unicode_ci,
  `capacidad_agua` int DEFAULT '0',
