  `proveedor` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `lugar_origen` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `es_embarcacion` enum('SI','NO') COLLATE utf8mb4_unicode_ci DEFAULT 'NO',
  `trailer_dominio` varchar(15) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `trailer_ejes` int DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
